query:
mutation GetLoginTokenFromCredentials($email: String!, $password: String!, $captchaToken: String, $origin: String!) {
  getLoginTokenFromCredentials(
    email: $email
    password: $password
    captchaToken: $captchaToken
    origin: $origin
  ) {
    loginToken {
      ...AuthTokenFragment
      __typename
    }
    __typename
  }
}

fragment AuthTokenFragment on AuthToken {
  token
  expiresAt
  __typename
}
